arguments.command:
python3 - <<'EOF' 2>/dev/null || node -e '
const fs=require("fs");const p="essay-the-sea.md";let s=fs.readFileSync(p,"utf8");
s=s.replace("The waves arriving at your feet were generated by weather hundreds of kilometres away, and they will keep arriving after you leave, with a patience that makes human urgency look like a nervous tic.","The waves arriving at your feet were generated by weather hundreds of kilometres away, and they will keep arriving after you leave, with a patience that makes human urgency look like a nervous tic. It has a sound, too, that most of us can hear in our heads without any help: a long, unhurried breathing, in and out, forever.");
s=s.replace("The change is worth noticing. The sea did not become empty; we simply stopped looking.","The change is worth noticing. The sea did not become empty; we simply stopped looking. Fishermen still read it the old way, by colour and wind and the behaviour of birds, and they are usually right.");
fs.writeFileSync(p,s);
console.log(s.split(/\s+/).filter(Boolean).length);
'

